"""Procedural Sindarosa rig parts + rig.json (fire dragon: crimson scaled body, ember belly bands, ribbed striped wings, long horned head). Original art generated by this
script (no legacy pixels used). Run: python3 tools/assets/rig-gen/sindarosa.py <out_rig_dir>  (needs Pillow + numpy)
Look matches the Fiara/Pax/Treenoc/Morblass/Rokcore rigs: cel-banded ramp, dark outline, pale upper-left rim.
"""
import json, os, sys, zlib
import numpy as np
from PIL import Image, ImageDraw, ImageFilter
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import palette

OUT = sys.argv[1]
os.makedirs(os.path.join(OUT, "parts"), exist_ok=True)
SS = 4
W = 80 * SS
FIRE = palette.ELEMENT_RAMPS["fire"]
SCALE = [(0.0, FIRE[0]), (0.3, (122, 30, 30)), (0.58, (160, 36, 40)), (0.82, (210, 72, 56)), (1.0, (250, 150, 100))]
OUTLINE = np.array(palette.outline("fire"), np.float32)
RIM = np.array((255, 224, 170), np.float32)
FACE = (30, 8, 8)
EYE = (255, 250, 170)

# geometry in the 80x80 rest frame, E view (y down)
G = {
 "tail": dict(pts=[(30,68),(18,72),(8,68),(5,58),(9,52),(13,60),(22,62),(32,60)], joint=(30,66), z=1, parent="torso", bias=-0.12),
 "wingB": dict(pts=[(42,38),(44,20),(52,6),(64,2),(62,16),(68,30),(54,36)], joint=(44,38), z=2, parent="torso", bias=-0.2, membrane=True),
 "torso": dict(pts=[(26,72),(23,54),(28,38),(40,32),(52,36),(58,50),(57,68),(42,74)], joint=(40,54), z=5, parent=None, bias=0.0, belly=True),
 "head": dict(pts=[(46,28),(46,15),(54,8),(66,10),(74,17),(68,22),(60,24),(56,32)], joint=(50,28), z=7, parent="torso", bias=0.08),
 "wingF": dict(pts=[(32,40),(24,22),(13,8),(4,3),(5,16),(1,28),(13,34),(20,44)], joint=(30,40), z=8, parent="torso", bias=0.12, membrane=True),
}

def view_tf(view, part):
    if view == "E":
        return dict(sx=1.0, dx=-3 if part == "head" else 0, dy=0)
    if view == "SE":
        d = dict(sx=0.93, dx=2, dy=1)
        if part == "head": d = dict(sx=1.06, dx=-8, dy=4, scale=1.06)
        if part == "armF": d = dict(sx=0.95, dx=-3, dy=1)
        if part == "armB": d = dict(sx=0.95, dx=3, dy=1)
        if part == "torso": d = dict(sx=0.96, dx=1, dy=2)
        return d
    d = dict(sx=0.93, dx=-1, dy=-1)  # NE: seen from behind
    if part == "head": d = dict(sx=0.92, dx=-6, dy=-2, scale=0.94)
    if part == "armF": d = dict(sx=0.95, dx=1, dy=-1)
    if part == "armB": d = dict(sx=0.95, dx=2, dy=-1)
    if part == "torso": d = dict(sx=1.0, dx=-2, dy=-1)
    return d

def apply(tf, p, c=(40, 40)):
    s = tf.get("scale", 1.0)
    return (c[0] + (p[0] - c[0]) * tf["sx"] * s + tf["dx"], c[1] + (p[1] - c[1]) * s + tf["dy"])

def noise(rs, scale, sx=1, sy=1):
    """Smooth noise, stretched sx/sy times (flow streaks)."""
    h = max(2, W // (scale * sy) + 2); w = max(2, W // (scale * sx) + 2)
    small = rs.rand(h, w)
    return np.asarray(Image.fromarray((small * 255).astype(np.uint8)).resize((W, W), Image.BICUBIC), np.float32) / 255.0

def render(name, view, pts, g, seed):
    m = Image.new("L", (W, W), 0)
    d = ImageDraw.Draw(m)
    d.polygon([(x * SS, y * SS) for x, y in pts], fill=255)
    if name == "head":  # horn and brow spikes
        for (bx, by) in ((50, 14), (54, 11)):
            d.polygon([(bx * SS, by * SS), ((bx - 4) * SS, (by - 7) * SS), ((bx + 3) * SS, (by - 1) * SS)], fill=255)
    m = m.filter(ImageFilter.GaussianBlur(SS * 0.35))
    ma = np.asarray(m, np.float32) / 255.0
    rs = np.random.RandomState(seed)
    mid = noise(rs, 4); fine = noise(rs, 2)
    yy, xx = np.mgrid[0:W, 0:W].astype(np.float32) / W
    t = 0.72 - 0.5 * yy - 0.2 * xx + 0.15 * (mid - 0.5) + 0.1 * (fine - 0.5) + g["bias"] + 0.25
    if g.get("membrane"):  # wing: dark ribs radiating from the joint over a red membrane
        jx, jy = g["joint"][0] / 80.0, g["joint"][1] / 80.0
        ang = np.arctan2(yy - jy, xx - jx)
        strut = np.abs(np.sin(ang * 7.0)) > 0.9
        t = np.where(strut, t - 0.35, t - 0.02)
    elif g.get("belly"):  # ember belly plates: horizontal bands on the front (east) side
        band = (np.abs(np.sin(yy * 22.0)) > 0.8) & (xx > 0.55)
        t = np.where(band, t + 0.3, t)
    else:  # overlapping scales
        sc = np.abs(np.sin(xx * 40.0)) * np.abs(np.sin(yy * 40.0)) > 0.8
        t = np.where(sc, t + 0.08, t)
    t = np.clip(np.round(np.clip(t, 0, 1) * 5.0) / 5.0, 0, 1)
    rgb = palette.ramp(SCALE, t)
    inner = np.asarray(m.filter(ImageFilter.MinFilter(SS * 3 + 1)), np.float32) / 255.0
    edge = np.clip(np.subtract(ma, inner), 0, 1)
    shifted = np.roll(np.roll(ma, SS * 2, axis=0), SS * 2, axis=1)
    lit = np.clip(np.subtract(ma, shifted), 0, 1) * inner.clip(0, 1)
    lit = np.asarray(Image.fromarray((lit * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(SS * 0.5)), np.float32) / 255.0
    rgb = rgb * (1 - 1.0 * edge[..., None]) + OUTLINE[None, None, :] * (1.0 * edge[..., None])
    rgb = rgb * (1 - 0.7 * lit[..., None]) + RIM[None, None, :] * (0.7 * lit[..., None])
    return Image.fromarray(np.dstack([np.clip(rgb, 0, 255), ma * 255.0]).astype(np.uint8), "RGBA")

def face(im, tf, view):
    d = ImageDraw.Draw(im)
    x, y = apply(tf, (60, 15))
    d.ellipse([x * SS - 2.0 * SS, y * SS - 1.4 * SS, x * SS + 2.0 * SS, y * SS + 1.4 * SS], fill=EYE + (255,))
    x, y = apply(tf, (70, 18))
    d.ellipse([x * SS - 1.0 * SS, y * SS - 0.7 * SS, x * SS + 1.0 * SS, y * SS + 0.7 * SS], fill=FACE + (255,))  # nostril

parts = []
for view in ("E", "SE", "NE"):
    tfs = {k: view_tf(view, k) for k in G}
    for k, g in G.items():
        pts = [apply(tfs[k], p) for p in g["pts"]]
        im = render(k, view, pts, g, zlib.crc32((k + view).encode()) % 9973 + 7)
        if k == "head" and view != "NE":
            face(im, tfs[k], view)
        small = im.resize((80, 80), Image.LANCZOS)
        a = np.asarray(small)
        ys, xs = np.nonzero(a[..., 3] > 8)
        x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
        crop = small.crop((x0, y0, x1, y1))
        fname = f"{k}.png" if view == "E" else f"{k}_{view.lower()}.png"
        crop.save(os.path.join(OUT, "parts", fname))
        parts.append(dict(view=view, id=k, png=fname, joint=apply(tfs[k], g["joint"]), off=(x0, y0), size=crop.size))

byv = {v: {e["id"]: e for e in parts if e["view"] == v} for v in ("E", "SE", "NE")}
def pv(e):
    return [int(round(e["joint"][0])) - e["off"][0], int(round(e["joint"][1])) - e["off"][1]]
def at(v, pid):
    g = G[pid]; e = byv[v][pid]
    jx, jy = int(round(e["joint"][0])), int(round(e["joint"][1]))
    if g["parent"] is None:
        return [jx, jy]
    pe = byv[v][g["parent"]]
    return [jx - int(round(pe["joint"][0])), jy - int(round(pe["joint"][1]))]

rig_parts = []
for pid in list(G):
    g = G[pid]
    p = {"id": pid}
    if g["parent"]: p["parent"] = g["parent"]
    p["png"] = byv["E"][pid]["png"]; p["pivot"] = pv(byv["E"][pid]); p["at"] = at("E", pid); p["z"] = g["z"]
    p["views"] = {v: {"png": byv[v][pid]["png"], "pivot": pv(byv[v][pid]), "at": at(v, pid)} for v in ("SE", "NE")}
    rig_parts.append(p)

def c(**kw): return kw
def c(**kw): return kw
actions = {
 "idle": dict(frames=4, curves={
    "torso": c(dy=[0, 0, -1, -1]),
    "head": c(rot=[0, 1, 2, 1], dy=[0, 0, 1, 0]),
    "wingF": c(rot=[0, -3, -5, -2]),
    "wingB": c(rot=[0, -2, -4, -1]),
    "tail": c(rot=[0, 3, 5, 2]),
 }),
 "walk": dict(frames=4, curves={  # waddle: wings flap lightly, tail swings
    "torso": c(rot=[-2, 0, 2, 0], dy=[1, 0, 1, 0]),
    "head": c(rot=[2, 0, -2, 0]),
    "wingF": c(rot=[-8, 4, -8, 4]),
    "wingB": c(rot=[-6, 3, -6, 3]),
    "tail": c(rot=[6, 0, -6, 0]),
 }),
 # fire roar: head rears back, wings spread wide, then snap forward
 "cast": dict(frames=4, curves={
    "torso": c(rot=[0, -3, -4, 2], dy=[0, -1, -2, 1]),
    "head": c(rot=[0, -10, -16, 6]),
    "wingF": c(rot=[0, -22, -36, -8]),
    "wingB": c(rot=[0, -18, -30, -6]),
    "tail": c(rot=[0, 6, 10, -4]),
 }),
}

json.dump(dict(dirs=["E", "SE", "NE"], parts=rig_parts, actions=actions), open(os.path.join(OUT, "rig.json"), "w"), indent=2)
open(os.path.join(OUT, "license.txt"), "w").write(
"""Rig parts for sindarosa: original art generated by tools/assets/rig-gen/sindarosa.py (WP-art-consistency-batches, 2026-11-12, Claude). No pixels
are copied; silhouette and colours chosen by eye after the legacy public/assets/img/map/sindarosa.png. Licence: same as the
repository's own original code and art (still to be decided in README.md; owner to confirm).
""")
print("ok")
